<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { Activity, ArrowDown, ArrowUp, ArrowLeft, ArrowRight, BarChart3, Bell, BookOpen, Check, ChevronDown, CircleHelp, Clock3, Copy, Download, Eye, FilePlus2, Filter, Folder, Gamepad2, Grid2X2, Image, ListChecks, LockKeyhole, LogOut, Maximize, Menu, Minimize, MoreHorizontal, Play, Plus, QrCode, Search, Settings2, Share2, Sparkles, Timer, Trophy, Trash2, Users, X } from 'lucide-vue-next'
