import { supabase } from './lib/supabase'
type Q = {id:number|string; type:string; prompt:string; options:string[]; correct:number; correctIndices?:number[]; minValue?:number; maxValue?:number; correctValue?:number; target?:{x:number;y:number}; seconds:number; points:number; explanation?:string}
