 {id:1,title:'Sains di sekitar kita',category:'Sains',updated:'Baru saja',color:'mint',published:true,questions:[{id:11,type:'Quiz',prompt:'Planet mana yang dikenal sebagai Planet Merah?',options:['Venus','Mars','Jupiter','Merkurius'],correct:1,seconds:20,points:1000},{id:12,type:'True or false',prompt:'Tumbuhan menghasilkan oksigen saat fotosintesis.',options:['Benar','Salah'],correct:0,seconds:15,points:1000},{id:13,type:'Quiz',prompt:'Air mendidih pada suhu berapa di permukaan laut?',options:['80°C','90°C','100°C','120°C'],correct:2,seconds:20,points:1000}]},
 {id:2,title:'Mengenal Indonesia',category:'Geografi',updated:'Kemarin',color:'peach',published:true,questions:[{id:21,type:'Quiz',prompt:'Apa ibu kota Provinsi Bali?',options:['Denpasar','Singaraja','Tabanan','Ubud'],correct:0,seconds:20,points:1000},{id:22,type:'Quiz',prompt:'Pulau terbesar di Indonesia adalah…',options:['Jawa','Sumatra','Kalimantan','Sulawesi'],correct:2,seconds:20,points:1000}]},
 {id:3,title:'Pemanasan: Tebak cepat',category:'Umum',updated:'3 hari lalu',color:'lavender',published:true,questions:[{id:31,type:'Quiz',prompt:'Berapa jumlah sisi pada segitiga?',options:['2','3','4','5'],correct:1,seconds:15,points:1000}]}
]
const load = <T,>(k:string,f:T):T => { try {const x=localStorage.getItem(k); return x?JSON.parse(x):f} catch{return f} }
const quizzes=ref<Quiz[]>(load('rq-quizzes',seed)); watch(quizzes,v=>localStorage.setItem('rq-quizzes',JSON.stringify(v)),{deep:true})
const adminRoute=window.location.pathname.replace(/\/+$/,'')==='/admin'
const page=ref(adminRoute?'library':'landing'), activeTab=ref('Semua kuis'), search=ref(''), toast=ref(''), showMobile=ref(false), modal=ref(''), qrOpen=ref(false), qrDataUrl=ref(''), qrUrl=ref(''), locked=ref(false), intentionalSignOut=ref(false)
const selected=ref<Quiz>(quizzes.value[0]); const editorTitle=ref(''); const draft=ref<Q[]>([]); const activeQ=ref(0); const quizName=ref(''); const joinPin=ref(new URLSearchParams(window.location.search).get('pin')?.replace(/\D/g,'').slice(0,8)||''); const playerName=ref(''); const playerAvatar=ref('🦊'); const typedAnswer=ref(''); const selectedAnswers=ref<number[]>([]); const scaleValue=ref(4); const playerMapAnswer=ref<{x:number;y:number}|null>(null); const joinError=ref(''); const typeMenu=ref(false); const questionTypeGroups=[{title:'Create quizzes',items:[{label:'Quiz',type:'quiz',emoji:'🎯'},{label:'True or false',type:'true_false',emoji:'◐'},{label:'Type answer',type:'type_answer',emoji:'T'},{label:'Slider',type:'slider',emoji:'↔'},{label:'Pin answer',type:'pin_answer',emoji:'📍'},{label:'Puzzle',type:'puzzle',emoji:'🧩'}]},{title:'Collect opinions',items:[{label:'Poll',type:'poll',emoji:'◒'},{label:'Scale',type:'scale',emoji:'1–5'},{label:'NPS scale',type:'nps_scale',emoji:'0–10'},{label:'Drop pin',type:'drop_pin',emoji:'🗺️'},{label:'Word cloud',type:'word_cloud',emoji:'☁️'},{label:'Open-ended',type:'open_ended',emoji:'💬'},{label:'Brainstorm',type:'brainstorm',emoji:'💡'}]}]; const questionTypes=questionTypeGroups.flatMap(g=>g.items); const avatars=['🦊','🐼','🐸','🐙','🦉','🐳','🐯','🐰','🐢','🦄','🐨','🐵']; const answerChoice=ref<number|null>(null); const submitted=ref(false)
const session=ref(load<any>('rq-session',null)); const remoteSession=ref(Boolean(session.value?.remote)); const remoteQuestion=ref<Q|null>(null); const remoteQuizTitle=ref(''); const remoteQuestionCount=ref(0); const remoteParticipantCount=ref(0); const participantAvatars=ref<Record<string,string>>({}); const realtimeChannel=ref<any>(null); const livePhase=ref('lobby'); const participants=ref<string[]>(['Alya','Bima','Citra','Dimas','+ 18 lainnya']); const currentQ=ref(0); const secs=ref(20); const runTimer=ref<any>(null); const remotePoll=ref<any>(null); const scoreRows=ref(load<any[]>('rq-scores',[{name:'Alya',score:2400,correct:3},{name:'Bima',score:1800,correct:2},{name:'Citra',score:1600,correct:2},{name:'Dimas',score:900,correct:1}]));
const authUser=ref<any>(null), authMode=ref<'signin'|'signup'>('signin'), authEmail=ref(''), authPassword=ref(''), authDisplayName=ref(''), authBusy=ref(false), authListener=ref<any>(null)
const tabs=['Semua kuis','Dibuat oleh saya','Favorit']; const filtered=computed(()=>quizzes.value.filter(q=>(activeTab.value==='Semua kuis'||activeTab.value==='Dibuat oleh saya'||activeTab.value==='Favorit')&&q.title.toLowerCase().includes(search.value.toLowerCase())))
const currentQuiz=computed(()=>{const q=quizzes.value.find(q=>q.id===selected.value?.id)||selected.value;return remoteSession.value&&remoteQuizTitle.value?{...q,title:remoteQuizTitle.value}:q})
const activeQuestion=computed(()=>remoteSession.value?remoteQuestion.value:currentQuiz.value?.questions[currentQ.value])
const isHostFullscreen=ref(false)
const playerPlacement=computed(()=>scoreRows.value.findIndex((p:any)=>p.name===playerName.value)+1)
const podiumLeaders=computed(()=>scoreRows.value.slice(0,3))
const qrLocalOnly=computed(()=>Boolean(qrUrl.value)&&['localhost','127.0.0.1'].includes(new URL(qrUrl.value).hostname))
watch(()=>activeQuestion.value?.id,(id,old)=>{if(id!==old){selectedAnswers.value=[];typedAnswer.value='';playerMapAnswer.value=null;const q=activeQuestion.value;if(q&&['Slider','Scale','NPS scale'].includes(q.type))scaleValue.value=Math.round(((q.minValue??0)+(q.maxValue??10))/2)}})
watch(()=>session.value?.pin,(pin)=>{if(pin)void generateSessionQr(pin)},{immediate:true})
function ping(s:string){toast.value=s;setTimeout(()=>toast.value='',2600)}
function nav(p:string){page.value=p;showMobile.value=false}
async function toggleHostFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{ping('Mode layar penuh tidak tersedia di browser ini')}}
function syncHostFullscreen(){isHostFullscreen.value=Boolean(document.fullscreenElement)}
function publicJoinUrl(){const base=import.meta.env.VITE_PUBLIC_APP_URL?.trim()||window.location.origin;const url=new URL('/',base);url.searchParams.set('pin',String(session.value?.pin||''));return url.toString()}
async function generateSessionQr(pin:string){try{const base=import.meta.env.VITE_PUBLIC_APP_URL?.trim()||window.location.origin;const url=new URL('/',base);url.searchParams.set('pin',pin);qrUrl.value=url.toString();qrDataUrl.value=await QRCode.toDataURL(qrUrl.value,{width:300,margin:2,errorCorrectionLevel:'M',color:{dark:'#203d2d',light:'#ffffff'}})}catch(e:any){qrDataUrl.value='';ping(`QR gagal dibuat: ${e.message||'coba lagi'}`)}}
async function openSessionQr(){if(!qrDataUrl.value&&session.value?.pin)await generateSessionQr(session.value.pin);qrOpen.value=Boolean(qrDataUrl.value)}
async function copyInviteLink(){try{await navigator.clipboard.writeText(publicJoinUrl());ping('Tautan undangan disalin')}catch{copyPin()}}
const apiBase=import.meta.env.VITE_API_URL||'http://localhost:8787'
async function api(path:string, body?:unknown, method='GET', token?:string){const auth=await supabase?.auth.getSession();if(auth?.error)throw auth.error;const bearer=token||auth?.data.session?.access_token;const res=await fetch(`${apiBase}${path}`,{method,headers:{'Content-Type':'application/json',...(bearer?{Authorization:`Bearer ${bearer}`}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json().catch(()=>({}));if(res.status===401&&authUser.value){void supabase?.auth.signOut();throw new Error('SESSION_EXPIRED')}if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);return data}
function typeCode(label:string){return questionTypes.find(x=>x.label===label)?.type||'quiz'}
function typeLabel(code:string){return questionTypes.find(x=>x.type===code)?.label||'Quiz'}
function questionInstructions(type:string){return ({'Quiz':'Pilih satu jawaban yang menurutmu benar.','True or false':'Pilih benar atau salah.','Type answer':'Ketik jawaban singkatmu.','Slider':'Geser mendekati nilai yang benar.','Pin answer':'Tandai lokasi yang diminta.','Puzzle':'Pilih opsi berdasarkan urutan yang benar.','Poll':'Pilih opsi yang paling sesuai.','Scale':'Geser untuk memberi nilai.','NPS scale':'Seberapa besar kemungkinan kamu merekomendasikan ini?','Drop pin':'Tandai lokasi pilihanmu.','Word cloud':'Kirim satu kata yang mewakili idemu.','Open-ended':'Tuliskan tanggapanmu.','Brainstorm':'Bagikan ide untuk dikumpulkan bersama.'} as Record<string,string>)[type]||'Ikuti petunjuk pengajar untuk menjawab.'}
function apiQuestions(){return draft.value.map(q=>({type:typeCode(q.type),prompt:q.prompt,options:q.options,correctIndex:q.correct,correctIndices:q.correctIndices,minValue:q.minValue,maxValue:q.maxValue,target:q.target,correctValue:q.correctValue,seconds:Number(q.seconds)||20,points:Number(q.points)||0,explanation:q.explanation}))}
const importInput=ref<HTMLInputElement|null>(null)
const templateHeaders=['quiz_title','category','type','prompt','option_a','option_b','option_c','option_d','option_e','option_f','option_g','option_h','correct_answer','duration_seconds','points','min_value','max_value','target_x','target_y','explanation']
async function downloadQuizTemplate(){const XLSX=await import('xlsx');const wb=XLSX.utils.book_new();const guide=[['TEMPLATE IMPORT KUIS RUANG KUIS'],['Isi sheet Questions sesuai kolom; ganti/hapus contoh baris sebelum upload. Setiap baris adalah satu soal.'],['Kolom type: quiz, true_false, type_answer, slider, pin_answer, puzzle, poll, scale, nps_scale, drop_pin, word_cloud, open_ended, brainstorm'],['correct_answer: quiz/true_false isi huruf opsi (A-H) atau teks opsi; type_answer isi kunci teks; slider isi angka benar; puzzle isi urutan huruf, contoh A,C,B. Tipe opini boleh kosong.'],['duration_seconds: 5-240; points: 0-10000. Scale/NPS min_value dan max_value opsional; default 1-5 atau 0-10. Pin answer wajib target_x dan target_y (0-1).'],['Contoh ini bisa langsung diimpor. Ubah atau hapus baris contoh sebelum menambahkan soal milikmu.']];const help=XLSX.utils.aoa_to_sheet(guide);help['!cols']=[{wch:130}];const questions=XLSX.utils.aoa_to_sheet([templateHeaders,['Contoh Kuis','Umum','quiz','Planet yang dikenal sebagai Planet Merah?','Venus','Mars','Jupiter','Merkurius','','','','','B',20,1000,'','','','','Mars adalah planet merah karena oksida besi di permukaannya.']]);questions['!cols']=templateHeaders.map(h=>({wch:Math.max(15,h.length+2)}));XLSX.utils.book_append_sheet(wb,help,'Petunjuk');XLSX.utils.book_append_sheet(wb,questions,'Questions');XLSX.writeFile(wb,'template-import-kuis-ruang-kuis.xlsx')}
function readCell(row:Record<string,any>,key:string){const value=row[key];return value===undefined||value===null?'':String(value).trim()}
async function importQuizExcel(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{const XLSX=await import('xlsx');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});const sheet=wb.Sheets.Questions||wb.Sheets[wb.SheetNames.find(n=>n.toLowerCase()==='questions')||''];if(!sheet)throw new Error('Sheet "Questions" tidak ditemukan. Gunakan template Ruang Kuis.');const rows=XLSX.utils.sheet_to_json<Record<string,any>>(sheet,{defval:'',raw:false});if(!rows.length)throw new Error('Sheet Questions belum berisi soal.');const missing=templateHeaders.filter(h=>!(h in rows[0]));if(missing.length)throw new Error(`Kolom template kurang: ${missing.join(', ')}`);const codes=new Set(questionTypes.map(t=>t.type));const parsed:Q[]=rows.map((row,i)=>{const n=i+2,rawType=readCell(row,'type').toLowerCase().replace(/[ -]+/g,'_'),type=rawType==='true_or_false'?'true_false':rawType; if(!codes.has(type))throw new Error(`Baris ${n}: tipe "${readCell(row,'type')}" tidak dikenal.`);const prompt=readCell(row,'prompt');if(!prompt)throw new Error(`Baris ${n}: prompt wajib diisi.`);const options='abcdefgh'.split('').map(c=>readCell(row,`option_${c}`)).filter(Boolean);const correctRaw=readCell(row,'correct_answer');const letters=(s:string)=>s.split(/[,;>]+/).map(x=>x.trim().toUpperCase()).filter(Boolean).map(x=>x.length===1&&x>='A'&&x<='H'?x.charCodeAt(0)-65:options.findIndex(o=>o.toLowerCase()===x.toLowerCase()));let correct=0,correctIndices:number[]|undefined;if(type==='true_false'&&options.length!==2)throw new Error(`Baris : true_false harus memiliki tepat dua opsi.`);if(['quiz','true_false','poll','puzzle'].includes(type)&&options.length<2)throw new Error(`Baris ${n}: tipe ${type} perlu minimal dua opsi.`);if(['quiz','true_false'].includes(type)){const idx=letters(correctRaw)[0]??options.findIndex(o=>o.toLowerCase()===correctRaw.toLowerCase());if(idx<0||idx>=options.length)throw new Error(`Baris ${n}: correct_answer harus berupa huruf opsi atau teks opsi.`);correct=idx}if(type==='type_answer'){if(!correctRaw)throw new Error(`Baris ${n}: isi correct_answer untuk kunci jawaban.`);options.splice(0,options.length,correctRaw)}if(type==='puzzle'){correctIndices=letters(correctRaw);if(correctIndices.length!==options.length||correctIndices.some(x=>x<0))throw new Error(`Baris ${n}: urutan puzzle harus memuat semua opsi, contoh A,C,B.`)}const numeric=(key:string,fallback?:number)=>{const v=readCell(row,key);if(!v)return fallback;const n=Number(v);if(!Number.isFinite(n))throw new Error(`Baris ${i+2}: ${key} harus angka.`);return n};const minValue=numeric('min_value',type==='nps_scale'?0:['slider','scale'].includes(type)?1:undefined),maxValue=numeric('max_value',type==='nps_scale'?10:['slider','scale'].includes(type)?(type==='slider'?100:5):undefined),correctValue=type==='slider'?numeric('correct_answer'):undefined;let target:Q['target'];if(type==='pin_answer'){const x=numeric('target_x'),y=numeric('target_y');if(x===undefined||y===undefined||x<0||x>1||y<0||y>1)throw new Error(`Baris ${n}: pin_answer wajib memiliki target_x dan target_y antara 0 dan 1.`);target={x,y}}if(['slider','scale','nps_scale'].includes(type)&&(minValue===undefined||maxValue===undefined||minValue>=maxValue))throw new Error(`Baris ${n}: rentang min_value/max_value tidak valid.`);if(type==='slider'&&(correctValue===undefined||correctValue<minValue!||correctValue>maxValue!))throw new Error(`Baris ${n}: correct_answer slider harus berada dalam rentang.`);const seconds=numeric('duration_seconds',20)!,points=numeric('points',['poll','scale','nps_scale','drop_pin','word_cloud','open_ended','brainstorm'].includes(type)?0:1000)!;if(seconds<5||seconds>240||points<0||points>10000)throw new Error(`Baris ${n}: durasi harus 5-240 detik dan poin 0-10000.`);return{id:Date.now()+i,type:typeLabel(type),prompt,options,correct,correctIndices,minValue,maxValue,correctValue,target,seconds,points}});parsed.forEach((q,i)=>q.explanation=readCell(rows[i],"explanation")||undefined);const first=rows[0];const quiz:Quiz={id:Date.now(),title:readCell(first,'quiz_title')||file.name.replace(/\.[^.]+$/,''),category:readCell(first,'category')||'Umum',updated:'Baru diimpor',color:'mint',published:false,questions:parsed};quizzes.value.unshift(quiz);selected.value=quiz;editorTitle.value=quiz.title;draft.value=JSON.parse(JSON.stringify(parsed));activeQ.value=0;nav('editor');ping(`${parsed.length} soal berhasil diimpor. Periksa lalu simpan atau terbitkan.`)}catch(e:any){ping(`Impor Excel gagal: ${e.message}`)}finally{(event.target as HTMLInputElement).value=''}}
function setQuestionType(item:any){const q=draft.value[activeQ.value];if(!q)return;q.type=item.label;typeMenu.value=false;if(item.type==='true_false')q.options=['Benar','Salah'];else if(item.type==='type_answer')q.options=['Jawaban benar'];else if(['slider','scale','nps_scale'].includes(item.type)){q.minValue=item.type==='nps_scale'?0:1;q.maxValue=item.type==='slider'?100:item.type==='nps_scale'?10:5;q.correctValue=item.type==='slider'?50:undefined;q.options=[]}else if(['pin_answer','drop_pin','slide','word_cloud','open_ended','brainstorm'].includes(item.type)){q.options=[];if(item.type==='pin_answer')q.target={x:.5,y:.5};else if(item.type==='drop_pin')q.target=undefined}else if(item.type==='poll')q.options=['Pilihan A','Pilihan B','Pilihan C','Pilihan D'];else if(q.options.length<2)q.options=['Pilihan A','Pilihan B','Pilihan C','Pilihan D'];if(item.type==='multi_select')q.correctIndices=[q.correct];if(item.type==='puzzle')q.correctIndices=q.options.map((_,i)=>i);if(['poll','scale','nps_scale','drop_pin','word_cloud','open_ended','brainstorm','slide'].includes(item.type))q.points=0;if(q.correct>=q.options.length)q.correct=0}
function setMapTarget(e:MouseEvent,forPlayer=false){const rect=(e.currentTarget as HTMLElement).getBoundingClientRect();const target={x:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height))};if(forPlayer)playerMapAnswer.value=target;else if(draft.value[activeQ.value])draft.value[activeQ.value].target=target}

async function loadRemoteQuizzes(){if(!authUser.value)return;try{const data=await api('/api/v1/quizzes');const rows:Quiz[]=data.quizzes.map((r:any,i:number)=>({id:r.id,title:r.title,category:r.category,updated:'Tersimpan di Supabase',color:['mint','peach','lavender'][i%3],published:r.status==='published',server:true,latestVersionId:r.latestVersionId,questions:(r.draft?.questions||[]).map((q:any,j:number)=>({id:j+1,type:typeLabel(q.type),prompt:q.prompt,options:q.options||[],correct:q.correctIndex??0,correctIndices:q.correctIndices,minValue:q.minValue,maxValue:q.maxValue,target:q.target,correctValue:q.correctValue,explanation:q.explanation,seconds:q.seconds??20,points:q.points??1000}))}));quizzes.value=rows;if(rows.length)selected.value=rows[0]}catch(e:any){ping(`Gagal memuat kuis: ${e.message}`)}}
function openAuth(){if(!supabase){ping('Supabase belum dikonfigurasi di .env');return}modal.value=authUser.value?'account':'auth'}
async function submitAuth(){if(!supabase)return;authBusy.value=true;try{const result=authMode.value==='signup'?await supabase.auth.signUp({email:authEmail.value,password:authPassword.value,options:{data:{display_name:authDisplayName.value||authEmail.value.split('@')[0]}}}):await supabase.auth.signInWithPassword({email:authEmail.value,password:authPassword.value});if(result.error)throw result.error;if(result.data.session){authUser.value=result.data.user;modal.value='';nav('library');await loadRemoteQuizzes();ping(authMode.value==='signup'?'Akun berhasil dibuat':'Berhasil masuk')}else ping('Cek email untuk menyelesaikan pendaftaran')}catch(e:any){ping(e.message||'Autentikasi gagal')}finally{authBusy.value=false}}
async function signOut(){intentionalSignOut.value=true;await supabase?.auth.signOut();authUser.value=null;modal.value='';nav('landing');quizzes.value=load('rq-quizzes',seed);selected.value=quizzes.value[0];intentionalSignOut.value=false;ping('Kamu sudah keluar')}
function connectRealtime(){if(!supabase||!session.value?.realtimeTopic)return;if(realtimeChannel.value)supabase.removeChannel(realtimeChannel.value);realtimeChannel.value=supabase.channel(session.value.realtimeTopic,{config:{private:true}}).on('broadcast',{event:'session_event'},()=>void refreshRemoteSnapshot(session.value?.participantToken)).subscribe()}
onMounted(async()=>{document.addEventListener('fullscreenchange',syncHostFullscreen);if(supabase){const {data,error}=await supabase.auth.getSession();authUser.value=data.session?.user||null;if(authUser.value){if(adminRoute)nav('library');else nav('landing');void loadRemoteQuizzes()}else if(error){await supabase.auth.signOut()}else if(adminRoute)openAuth();const {data:listener}=supabase.auth.onAuthStateChange((event,s)=>{const hadUser=Boolean(authUser.value);authUser.value=s?.user||null;if(s?.user){if(adminRoute&&page.value==='landing')nav('library');if(event==='SIGNED_IN'||event==='INITIAL_SESSION')setTimeout(()=>void loadRemoteQuizzes(),0)}else if(event==='SIGNED_OUT'&&hadUser&&!intentionalSignOut.value){nav('landing');modal.value='auth';ping('Sesi login berakhir. Silakan masuk kembali.')}});authListener.value=listener.subscription;if(remoteSession.value){beginRemotePolling();connectRealtime()}}else if(adminRoute)openAuth()})
onUnmounted(()=>{document.removeEventListener('fullscreenchange',syncHostFullscreen);authListener.value?.unsubscribe();if(realtimeChannel.value)supabase?.removeChannel(realtimeChannel.value);clearInterval(runTimer.value);clearInterval(remotePoll.value)})
function makeQuiz(){const q:Quiz={id:Date.now(),title:'Kuis tanpa judul',category:'Umum',updated:'Baru saja',color:['mint','peach','lavender'][Math.floor(Math.random()*3)],published:false,questions:[{id:Date.now(),type:'Quiz',prompt:'Tulis pertanyaan di sini',options:['Pilihan A','Pilihan B','Pilihan C','Pilihan D'],correct:0,seconds:20,points:1000}]};quizzes.value.unshift(q);selected.value=q;editorTitle.value=q.title;draft.value=JSON.parse(JSON.stringify(q.questions));activeQ.value=0;nav('editor')}
function editQuiz(q:Quiz){selected.value=q;editorTitle.value=q.title;draft.value=JSON.parse(JSON.stringify(q.questions));activeQ.value=0;nav('editor')}
async function saveDraft(publish=false){const q=quizzes.value.find(x=>x.id===selected.value.id);if(q){q.title=editorTitle.value.trim()||'Kuis tanpa judul';q.questions=JSON.parse(JSON.stringify(draft.value));q.updated='Baru saja';selected.value=q}if(authUser.value){try{const body={title:editorTitle.value.trim()||'Kuis tanpa judul',category:q?.category||'Umum',questions:apiQuestions()};const saved=q?.server?await api(`/api/v1/quizzes/${q.id}`,body,'PATCH'):await api('/api/v1/quizzes',body,'POST');const record=saved.quiz;if(q){q.id=record.id;q.server=true;selected.value=q}if(publish){const result=await api(`/api/v1/quizzes/${record.id}/publish`,{},'POST');if(q){q.published=true;q.latestVersionId=result.version.id}}}catch(e:any){ping(`Belum tersimpan ke server: ${e.message}`);return null}}else if(publish){ping('Masuk ke akun pengajar dulu agar PIN sesi tersimpan dan bisa diakses peserta.');openAuth();return null}ping(publish?'Kuis diterbitkan':'Perubahan tersimpan');return q||null}
function previewQuiz(){saveDraft().then(q=>{if(q)nav('preview')})}
function addQuestion(){draft.value.push({id:Date.now(),type:'Quiz',prompt:'Tulis pertanyaan di sini',options:['Pilihan A','Pilihan B','Pilihan C','Pilihan D'],correct:0,seconds:20,points:1000});activeQ.value=draft.value.length-1}
function addOption(){const q=draft.value[activeQ.value];if(q.options.length>=8){ping('Maksimal delapan pilihan');return}q.options.push(`Pilihan ${String.fromCharCode(65+q.options.length)}`);if(typeCode(q.type)==='puzzle')q.correctIndices=q.options.map((_,i)=>i)}
function removeOption(i:number){const q=draft.value[activeQ.value];if(q.options.length<=2){ping('Minimal dua pilihan untuk tipe soal ini');return}q.options.splice(i,1);q.correct=Math.min(q.correct,q.options.length-1);if(typeCode(q.type)==='multi_select')q.correctIndices=(q.correctIndices||[]).filter(x=>x!==i).map(x=>x>i?x-1:x);if(typeCode(q.type)==='puzzle')q.correctIndices=q.options.map((_,j)=>j)}
function moveOption(i:number,delta:number){const q=draft.value[activeQ.value];const to=i+delta;if(to<0||to>=q.options.length)return;[q.options[i],q.options[to]]=[q.options[to],q.options[i]];if(typeCode(q.type)==='puzzle')q.correctIndices=q.options.map((_,j)=>j)}
function markCorrect(i:number){const q=draft.value[activeQ.value];if(typeCode(q.type)==='multi_select'){const values=q.correctIndices||[];q.correctIndices=values.includes(i)?values.filter(x=>x!==i):[...values,i];if(!q.correctIndices.length)q.correctIndices=[i]}else q.correct=i}
function selectComplex(i:number){if(activeQuestion.value?.type==='Multi select'){selectedAnswers.value=selectedAnswers.value.includes(i)?selectedAnswers.value.filter(x=>x!==i):[...selectedAnswers.value,i]}else if(activeQuestion.value?.type==='Puzzle'){selectedAnswers.value=selectedAnswers.value.includes(i)?selectedAnswers.value:[...selectedAnswers.value,i]}}
function deleteQuestion(){if(draft.value.length<2){ping('Kuis harus memiliki setidaknya satu soal');return}draft.value.splice(activeQ.value,1);activeQ.value=Math.max(0,activeQ.value-1)}
async function publishAndLaunch(){const q=await saveDraft(true);if(q)await startSession(q)}
async function startSession(q:Quiz){selected.value=q;if(supabase&&!authUser.value){ping('Masuk sebagai pengajar untuk membuat PIN sesi yang dapat dipakai peserta.');openAuth();return}if(authUser.value){try{if(!q.server){const body={title:q.title,category:q.category,questions:q.questions.map(x=>({type:typeCode(x.type),prompt:x.prompt,options:x.options,correctIndex:x.correct,correctIndices:x.correctIndices,minValue:x.minValue,maxValue:x.maxValue,target:x.target,correctValue:x.correctValue,seconds:x.seconds,points:x.points}))};const made=await api('/api/v1/quizzes',body,'POST');q.id=made.quiz.id;q.server=true}if(!q.latestVersionId){const body={title:q.title,category:q.category,questions:q.questions.map(x=>({type:typeCode(x.type),prompt:x.prompt,options:x.options,correctIndex:x.correct,correctIndices:x.correctIndices,minValue:x.minValue,maxValue:x.maxValue,target:x.target,correctValue:x.correctValue,seconds:x.seconds,points:x.points}))};await api(`/api/v1/quizzes/${q.id}`,body,'PATCH');const version=await api(`/api/v1/quizzes/${q.id}/publish`,{},'POST');q.latestVersionId=version.version.id;q.published=true}const result=await api('/api/v1/sessions',{quizId:q.id},'POST');session.value={...result.session,quizId:q.id,remote:true,createdAt:Date.now()};remoteSession.value=true;localStorage.setItem('rq-session',JSON.stringify(session.value));participants.value=[];currentQ.value=-1;livePhase.value='lobby';remoteQuizTitle.value=q.title;nav('host');beginRemotePolling();connectRealtime();await refreshRemoteSnapshot();return}catch(e:any){ping(`Sesi gagal dibuat: ${e.message}`);return}}session.value={pin:String(Math.floor(100000+Math.random()*900000)),quizId:q.id,createdAt:Date.now()};remoteSession.value=false;localStorage.setItem('rq-session',JSON.stringify(session.value));participants.value=['Alya','Bima','Citra','Dimas','+ 18 lainnya'];currentQ.value=0;livePhase.value='lobby';nav('host')}
async function startGame(){if(remoteSession.value){await hostCommand('START');return}livePhase.value='question';secs.value=activeQuestion.value?.seconds||20;startClock()}
function startClock(){clearInterval(runTimer.value);runTimer.value=setInterval(()=>{if(secs.value>0)secs.value--;else lockAnswer()},1000)}
function beginRemotePolling(){clearInterval(remotePoll.value);remotePoll.value=setInterval(()=>void refreshRemoteSnapshot(),1200)}
async function refreshRemoteSnapshot(token?:string){if(!remoteSession.value||!session.value?.id)return;try{const data=await api(`/api/v1/sessions/${session.value.id}/snapshot`,undefined,'GET',token||session.value.participantToken);const s=data.session;const previousQuestion=currentQ.value;session.value={...session.value,stateVersion:s.stateVersion,eventSeq:s.eventSeq,remote:true};localStorage.setItem('rq-session',JSON.stringify(session.value));remoteQuizTitle.value=data.quiz.title||remoteQuizTitle.value;remoteQuestionCount.value=data.quiz.questionCount||remoteQuestionCount.value;remoteParticipantCount.value=data.participantCount??remoteParticipantCount.value;currentQ.value=s.questionIndex;if(previousQuestion!==s.questionIndex){submitted.value=false;answerChoice.value=null;selectedAnswers.value=[];typedAnswer.value='';playerMapAnswer.value=null}livePhase.value=s.state==='lobby'?'lobby':s.state==='question_open'||s.state==='question_locked'?'question':s.state==='reveal'||s.state==='leaderboard'?'reveal':s.state==='podium'||s.state==='finished'?'podium':'lobby';if(data.question){remoteQuestion.value={id:data.question.id,type:typeLabel(data.question.type),prompt:data.question.prompt,options:data.question.options,correct:data.question.answerKey?.correctIndex??-1,correctIndices:data.question.answerKey?.correctOrder,minValue:data.question.minValue,maxValue:data.question.maxValue,target:data.question.answerKey?.target,correctValue:data.question.answerKey?.correctValue,seconds:Math.ceil(data.question.durationMs/1000),points:1000}}if(s.deadlineAt)secs.value=Math.max(0,Math.ceil((new Date(s.deadlineAt).getTime()-Date.now())/1000));if(data.playerScore){const row=scoreRows.value.find((x:any)=>x.name===playerName.value);if(row){row.score=data.playerScore.score;row.correct=data.playerScore.correct}else scoreRows.value.unshift({name:playerName.value,score:data.playerScore.score,correct:data.playerScore.correct})}if(data.leaderboard)scoreRows.value=data.leaderboard.map((x:any)=>({name:x.nickname,avatar:x.avatar||participantAvatars.value[x.nickname]||"🦊",score:x.score,correct:x.correct}));if(data.participants){participants.value=data.participants.map((x:any)=>x.nickname);participantAvatars.value=Object.fromEntries(data.participants.map((x:any)=>[x.nickname,x.avatar||'🦊']))}}catch(e:any){if(e.message==='FORBIDDEN'||e.message==='INVALID_PARTICIPANT')ping('Token sesi tidak berlaku')}}
async function hostCommand(command:string){try{await api(`/api/v1/sessions/${session.value.id}/commands`,{command,expectedVersion:session.value.stateVersion},'POST');await refreshRemoteSnapshot()}catch(e:any){ping(`Aksi sesi gagal: ${e.message}`);await refreshRemoteSnapshot()}}
async function lockAnswer(){clearInterval(runTimer.value);if(remoteSession.value){await hostCommand('REVEAL');return}if(livePhase.value==='question')livePhase.value='reveal'}
async function nextQuestion(){if(remoteSession.value){await hostCommand('NEXT');return}if(currentQ.value<currentQuiz.value.questions.length-1){currentQ.value++;livePhase.value='question';secs.value=activeQuestion.value?.seconds||20;startClock()}else{livePhase.value='podium';scoreRows.value=scoreRows.value.map((p:any)=>({...p,score:p.score+Math.floor(Math.random()*500)})).sort((a:any,b:any)=>b.score-a.score);localStorage.setItem('rq-scores',JSON.stringify(scoreRows.value))}}
function activeLocalQuestion(){return currentQuiz.value?.questions[currentQ.value]}
async function doAnswer(answer:number|string|number[]|{x:number;y:number}){if(submitted.value)return;if(typeof answer==='string'&&!answer.trim()){ping('Tulis jawabanmu dulu');return}if(remoteSession.value){try{const token=session.value?.participantToken;const r=await api(`/api/v1/sessions/${session.value.id}/answers`,{questionId:activeQuestion.value?.id,requestId:crypto.randomUUID(),answer:typeof answer==='string'?answer.trim():answer},'POST',token);if(typeof answer==='number')answerChoice.value=answer;submitted.value=true;ping(r.receipt.isCorrect?'Jawaban benar, poin tercatat':'Jawaban sudah dicatat');await refreshRemoteSnapshot(token);return}catch(e:any){ping(`Jawaban belum terkirim: ${e.message}`);return}}if(typeof answer==='number')answerChoice.value=answer;submitted.value=true;const correct=typeof answer==='number'&&answer===activeQuestion.value?.correct||Array.isArray(answer)&&(activeQuestion.value?.type==='Multi select'&&answer.slice().sort().join(',')===(activeQuestion.value.correctIndices||[]).slice().sort().join(',')||activeQuestion.value?.type==='Puzzle'&&answer.join(',')===(activeQuestion.value.correctIndices||activeQuestion.value.options.map((_,i)=>i)).join(','));const me=playerName.value||'Tamu';const old=scoreRows.value.find((p:any)=>p.name===me);if(old){if(correct){old.correct++;old.score+=Math.round((activeQuestion.value?.points||1000)*(0.5+0.5*secs.value/(activeQuestion.value?.seconds||20)))}}else scoreRows.value.push({name:me,score:correct?Math.round((activeQuestion.value?.points||1000)*(0.5+0.5*secs.value/(activeQuestion.value?.seconds||20))):0,correct:correct?1:0});localStorage.setItem('rq-scores',JSON.stringify(scoreRows.value));}
async function joinGame(){joinError.value='';if(!joinPin.value.trim()){joinError.value='Masukkan kode akses kuis.';return}const me=playerName.value.trim()||`Tamu ${Math.floor(100+Math.random()*900)}`;playerName.value=me;if(supabase){try{const data=await api('/api/v1/join',{pin:joinPin.value.replace(/\s/g,''),nickname:me,avatar:playerAvatar.value},'POST');playerName.value=data.participant.nickname;session.value={id:data.sessionId,pin:joinPin.value,participantToken:data.participantToken,realtimeTopic:data.realtimeTopic,remote:true,createdAt:Date.now()};remoteSession.value=true;remoteQuizTitle.value=data.quizTitle;localStorage.setItem('rq-session',JSON.stringify(session.value));submitted.value=false;answerChoice.value=null;livePhase.value='lobby';nav('player');beginRemotePolling();connectRealtime();await refreshRemoteSnapshot(data.participantToken);return}catch(e:any){joinError.value=({SESSION_NOT_FOUND_OR_LOCKED:'PIN tidak ditemukan atau ruang tunggu sudah ditutup.',SESSION_FULL:'Ruang kuis sudah penuh.',JOIN_RATE_LIMITED:'Terlalu banyak percobaan. Coba lagi sebentar.',INTERNAL_ERROR:'Server gagal mencatat peserta. Coba lagi; jika masih terjadi, periksa log API.'} as any)[e.message]||(/fetch|network|failed to connect/i.test(e.message)?'Tidak dapat menghubungi API. Pastikan layanan API sedang aktif.':`Gagal bergabung: ${e.message}`);return}}if(!participants.value.includes(me))participants.value.unshift(me);nav('player');submitted.value=false;answerChoice.value=null;livePhase.value='question';currentQ.value=0;secs.value=activeQuestion.value?.seconds||20}
async function exportCsv(){let rows=scoreRows.value;if(remoteSession.value&&session.value?.id&&authUser.value){try{const result=await api(`/api/v1/sessions/${session.value.id}/results`);rows=result.results.map((r:any)=>({name:r.nickname,score:r.score,correct:r.correct}));scoreRows.value=rows}catch(e:any){ping(`Laporan gagal dimuat: ${e.message}`);return}}const csv=[['Nama','Skor','Jawaban benar'],...rows.map((p:any)=>[p.name,p.score,p.correct])].map(r=>r.join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='laporan-ruang-kuis.csv';a.click();URL.revokeObjectURL(a.href)}
function copyPin(){navigator.clipboard?.writeText(session.value?.pin||'').then(()=>ping('PIN disalin')).catch(()=>ping(`PIN: ${session.value?.pin}`))}
</script>

<template>
